import numpy as np
from collections import deque

inp = np.array(input_grid)

# Find all enclosed regions (by 8-connectivity through walls)
def find_enclosed_0_regions(grid):
    h, w = grid.shape

    # First, flood fill from outside to mark non-enclosed 0s
    visited = set()
    queue = deque()

    # Add all edge 0s as starting points for exterior flood
    for r in range(h):
        for c in [0, w-1]:
            if grid[r,c] == 0:
                visited.add((r,c))
                queue.append((r,c))
    for r in [0, h-1]:
        for c in range(w):
            if grid[r,c] == 0 and (r,c) not in visited:
                visited.add((r,c))
                queue.append((r,c))

    # Flood fill from these edge points
    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr, nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    # Any 0 not in visited is in an enclosed region
    enclosed_0s = set((r,c) for r in range(h) for c in range(w) 
                       if grid[r,c] == 0 and (r,c) not in visited)

    return enclosed_0s

