import numpy as np

test_grid = np.array(test_input)
h, w = test_grid.shape

# Find enclosed components (those not touching grid edge via 4-connectivity)
def find_enclosed_components(grid):
    h, w = grid.shape

    # Mark all 0s that touch the edge as "exterior"
    exterior = set()

    # Add edge 0s
    for r in range(h):
        if 0 <= r < h:
            for c in [0, w-1]:
                if grid[r,c] == 0:
                    exterior.add((r,c))
    for c in range(w):
        for r in [0, h-1]:
            if grid[r,c] == 0 and (r,c) not in exterior:
                exterior.add((r,c))

    # Propagate exterior through flood fill
    stack = list(exterior)
    visited = set(exterior)

    while stack:
        r, c = stack.pop()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr,nc] == 0 and (nr,nc) not in visited:
                visited.add((nr, nc))
                stack.append((nr, nc))

    # Any 0 not in visited is enclosed
    enclosed_cells = set((r,c) for r in range(h) for c in range(w) 
                          if grid[r,c] == 0 and (r,c) not in visited)

    return enclosed_cells

