def dist_to_nearest_nonzero(pos, grid):
    r, c = pos
    visited = set([pos])

    # BFS from this position until we hit a non-zero
    queue = deque([(r, c)])
    while queue:
        cr, cc = queue.popleft()
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if (nr, nc) not in visited:
                    val = grid[nr][nc]
                    if val != 0:
                        return abs(cr - nr) + abs(cc - nc)  # Manhattan distance
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return float('inf')

